  const shadow = pose === 'fist' ? '<ellipse cx="100" cy="190" rx="26" ry="5" fill="#0f172a" opacity=".25"/>' : '';
  const stars = '<path d="M30 40l3 7 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z" fill="#fde047"/><path d="M168 132l2 5 5 1-4 4 1 5-4-3-4 3 1-5-4-4 5-1z" fill="#fde047"/><circle cx="26" cy="120" r="3.5" fill="#f472b6"/><circle cx="176" cy="46" r="3.5" fill="#38bdf8"/>';
  const txt = `<text x="100" y="196" text-anchor="middle" font-family="Tahoma,Arial,sans-serif" font-weight="900" font-size="22" fill="#fff" stroke="#0f172a" stroke-width="5" paint-order="stroke" stroke-linejoin="round">${label}</text>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 200 200">${stars}${shadow}${body}${txt}</svg>`;
